import { createTimestamp } from "./runtimeMetadata";

export const SESSION_MEMORY_CONTINUITY_KINDS = Object.freeze([
  "working_state",
  "conversation_summary",
] as const);

export type SessionMemoryContinuityKind =
  (typeof SESSION_MEMORY_CONTINUITY_KINDS)[number];

export const SESSION_MEMORY_SCOPES = Object.freeze([
  "current_session",
] as const);

export type SessionMemoryScope = (typeof SESSION_MEMORY_SCOPES)[number];

export const SESSION_MEMORY_EXECUTION_MODES = Object.freeze([
  "async_background",
] as const);

export type SessionMemoryExecutionMode =
  (typeof SESSION_MEMORY_EXECUTION_MODES)[number];

export type RuntimeSessionMemoryWorkingState = Readonly<{
  currentGoal: string | null;
  openLoops: readonly string[];
  followUpConstraints: readonly string[];
  recentDecisions: readonly string[];
}>;

export type RuntimeSessionMemoryWorkingStateInput = Readonly<{
  currentGoal?: string | null;
  openLoops?: readonly string[];
  followUpConstraints?: readonly string[];
  recentDecisions?: readonly string[];
}>;

export type RuntimeSessionMemory = Readonly<{
  memoryId: string;
  layer: "session_memory";
  sessionId: string;
  scope: "current_session";
  continuityKinds: readonly SessionMemoryContinuityKind[];
  workingState: RuntimeSessionMemoryWorkingState;
  conversationSummary: string | null;
  updatedByJobId: string | null;
  runsAsynchronously: true;
  blocksMainInteraction: false;
  supportsCrossSessionDurableFacts: false;
  createdAt: string;
  updatedAt: string;
}>;

export type RuntimeSessionMemoryInput = Readonly<{
  memoryId?: string;
  sessionId: string;
  workingState?: RuntimeSessionMemoryWorkingStateInput;
  conversationSummary?: string | null;
  updatedByJobId?: string | null;
  createdAt?: string;
  updatedAt?: string;
}>;

export type RuntimeSessionMemoryRefreshJob = Readonly<{
  jobId: string;
  sessionId: string;
  memoryId: string;
  executionMode: "async_background";
  scope: "current_session";
  targetContinuityKinds: readonly SessionMemoryContinuityKind[];
  blocksMainInteraction: false;
  createdAt: string;
}>;

export type RuntimeSessionMemoryRefreshJobInput = Readonly<{
  jobId?: string;
  sessionId: string;
  memoryId: string;
  targetContinuityKinds?: readonly SessionMemoryContinuityKind[];
  createdAt?: string;
}>;

function assertNonEmptyString(value: string, fieldName: string): string {
  if (value.trim().length === 0) {
    throw new Error(`${fieldName} must be a non-empty string.`);
  }

  return value;
}

function normalizeOptionalString(
  value: string | null | undefined,
  fieldName: string,
): string | null {
  if (value == null) {
    return null;
  }

  return assertNonEmptyString(value, fieldName);
}

function freezeStringArray(
  values: readonly string[] | undefined,
  fieldName: string,
): readonly string[] {
  return Object.freeze(
    (values ?? []).map((value, index) =>
      assertNonEmptyString(value, `${fieldName}[${index}]`),
    ),
  );
}

function sanitizeSegment(value: string): string {
  return value.replace(/[^a-z0-9]+/gi, "-").replace(/^-+|-+$/g, "");
}

function assertContinuityKind(
  value: SessionMemoryContinuityKind,
): SessionMemoryContinuityKind {
  if (!SESSION_MEMORY_CONTINUITY_KINDS.includes(value)) {
    throw new Error(`Unsupported session memory continuity kind: ${value}.`);
  }

  return value;
}

function resolveTargetContinuityKinds(
  targetContinuityKinds: readonly SessionMemoryContinuityKind[] | undefined,
): readonly SessionMemoryContinuityKind[] {
  const resolved =
    targetContinuityKinds === undefined
      ? [...SESSION_MEMORY_CONTINUITY_KINDS]
      : Array.from(
          new Set(
            targetContinuityKinds.map((kind) => assertContinuityKind(kind)),
          ),
        );

  if (resolved.length === 0) {
    throw new Error("targetContinuityKinds must include at least one entry.");
  }

  return Object.freeze(resolved);
}

function createWorkingState(
  input: RuntimeSessionMemoryWorkingStateInput | undefined,
): RuntimeSessionMemoryWorkingState {
  return Object.freeze({
    currentGoal: normalizeOptionalString(input?.currentGoal, "currentGoal"),
    openLoops: freezeStringArray(input?.openLoops, "openLoops"),
    followUpConstraints: freezeStringArray(
      input?.followUpConstraints,
      "followUpConstraints",
    ),
    recentDecisions: freezeStringArray(
      input?.recentDecisions,
      "recentDecisions",
    ),
  });
}

export function createSessionMemoryId(
  sessionId: string,
  now: string = createTimestamp(),
): string {
  const sanitizedSessionId = sanitizeSegment(sessionId);
  const sanitizedNow = now.replace(/[-:.TZ]/g, "").toLowerCase();

  return `session-memory.${sanitizedSessionId}.${sanitizedNow}`;
}

export function createSessionMemoryRefreshJobId(
  sessionId: string,
  now: string = createTimestamp(),
): string {
  const sanitizedSessionId = sanitizeSegment(sessionId);
  const sanitizedNow = now.replace(/[-:.TZ]/g, "").toLowerCase();

  return `session-memory-job.${sanitizedSessionId}.${sanitizedNow}`;
}

export function createSessionMemory(
  input: RuntimeSessionMemoryInput,
): RuntimeSessionMemory {
  const createdAt = input.createdAt ?? createTimestamp();
  const updatedAt = input.updatedAt ?? createdAt;
  const sessionId = assertNonEmptyString(input.sessionId, "sessionId");

  return Object.freeze({
    memoryId: input.memoryId ?? createSessionMemoryId(sessionId, createdAt),
    layer: "session_memory",
    sessionId,
    scope: "current_session",
    continuityKinds: SESSION_MEMORY_CONTINUITY_KINDS,
    workingState: createWorkingState(input.workingState),
    conversationSummary: normalizeOptionalString(
      input.conversationSummary,
      "conversationSummary",
    ),
    updatedByJobId: normalizeOptionalString(
      input.updatedByJobId,
      "updatedByJobId",
    ),
    runsAsynchronously: true,
    blocksMainInteraction: false,
    supportsCrossSessionDurableFacts: false,
    createdAt,
    updatedAt,
  });
}

export function createSessionMemoryRefreshJob(
  input: RuntimeSessionMemoryRefreshJobInput,
): RuntimeSessionMemoryRefreshJob {
  const createdAt = input.createdAt ?? createTimestamp();
  const sessionId = assertNonEmptyString(input.sessionId, "sessionId");
  const memoryId = assertNonEmptyString(input.memoryId, "memoryId");

  return Object.freeze({
    jobId:
      input.jobId ?? createSessionMemoryRefreshJobId(sessionId, createdAt),
    sessionId,
    memoryId,
    executionMode: "async_background",
    scope: "current_session",
    targetContinuityKinds: resolveTargetContinuityKinds(
      input.targetContinuityKinds,
    ),
    blocksMainInteraction: false,
    createdAt,
  });
}

