import {
  createContextSnapshot,
  type RuntimeContextContribution,
  type RuntimeContextSnapshot,
} from "./contextSnapshot";
import {
  assembleContextSnapshot,
  type RuntimeContextAssemblyInput,
  type RuntimeContextAssemblyResult,
  type RuntimeContextExcludedContribution,
} from "./contextVisibility";
import {
  resolveContextContributionConflicts,
  type RuntimeContextConflictCandidate,
  type RuntimeContextUnresolvedConflict,
} from "./contextPrecedence";

export const CONTEXT_REFRESH_BOUNDARIES = Object.freeze([
  "turn_completion",
  "action_completion",
  "memory_update",
] as const);

export type ContextRefreshBoundary =
  (typeof CONTEXT_REFRESH_BOUNDARIES)[number];

export type RuntimeContextRefreshInput<TPayload = unknown> = Readonly<{
  previousSnapshot: RuntimeContextSnapshot<TPayload>;
  boundary: ContextRefreshBoundary;
  assembly: RuntimeContextAssemblyInput<TPayload>;
  conflictCandidates?: readonly RuntimeContextConflictCandidate<TPayload>[];
}>;

export type RuntimeContextRefreshResult<TPayload = unknown> = Readonly<{
  boundary: ContextRefreshBoundary;
  previousSnapshotId: string;
  refreshedSnapshot: RuntimeContextSnapshot<TPayload>;
  included: RuntimeContextAssemblyResult<TPayload>["included"];
  excluded: readonly RuntimeContextExcludedContribution<TPayload>[];
  selected: readonly RuntimeContextConflictCandidate<TPayload>[];
  shadowed: readonly RuntimeContextConflictCandidate<TPayload>[];
  unresolved: readonly RuntimeContextUnresolvedConflict<TPayload>[];
}>;

function assertRefreshBoundary(
  boundary: ContextRefreshBoundary,
): ContextRefreshBoundary {
  if (!CONTEXT_REFRESH_BOUNDARIES.includes(boundary)) {
    throw new Error(`Unsupported context refresh boundary: ${boundary}.`);
  }

  return boundary;
}

function createContributionIdSet<TPayload>(
  contributions: readonly RuntimeContextContribution<TPayload>[],
): ReadonlySet<string> {
  return new Set(
    contributions.map((contribution) => contribution.contributionId),
  );
}

function filterIncludedConflictCandidates<TPayload>(
  conflictCandidates: readonly RuntimeContextConflictCandidate<TPayload>[] | undefined,
  includedContributionIds: ReadonlySet<string>,
): readonly RuntimeContextConflictCandidate<TPayload>[] {
  return Object.freeze(
    (conflictCandidates ?? []).filter((candidate) =>
      includedContributionIds.has(candidate.candidate.contribution.contributionId),
    ),
  );
}

function createEffectiveSnapshot<TPayload>(
  snapshot: RuntimeContextSnapshot<TPayload>,
  selected: readonly RuntimeContextConflictCandidate<TPayload>[],
  unresolved: readonly RuntimeContextUnresolvedConflict<TPayload>[],
): RuntimeContextSnapshot<TPayload> {
  const managedContributionIds = new Set<string>();

  for (const candidate of selected) {
    managedContributionIds.add(candidate.candidate.contribution.contributionId);
  }

  for (const conflict of unresolved) {
    for (const candidate of conflict.candidates) {
      managedContributionIds.add(candidate.candidate.contribution.contributionId);
    }
  }

  const selectedContributionIds = new Set(
    selected.map((candidate) => candidate.candidate.contribution.contributionId),
  );

  const retainContribution = (
    contribution: RuntimeContextContribution<TPayload>,
  ): boolean =>
    !managedContributionIds.has(contribution.contributionId) ||
    selectedContributionIds.has(contribution.contributionId);

  return createContextSnapshot({
    snapshotId: snapshot.snapshotId,
    sessionId: snapshot.sessionId,
    turnId: snapshot.turnId,
    stage: snapshot.stage,
    sourceKinds: snapshot.sourceKinds,
    sessionState: snapshot.contributionsBySource.sessionState.filter(
      retainContribution,
    ),
    transcript: snapshot.contributionsBySource.transcript.filter(
      retainContribution,
    ),
    memoryState: snapshot.contributionsBySource.memoryState.filter(
      retainContribution,
    ),
    hostInput: snapshot.contributionsBySource.hostInput.filter(retainContribution),
    capabilityVisibility:
      snapshot.contributionsBySource.capabilityVisibility.filter(
        retainContribution,
      ),
    createdAt: snapshot.createdAt,
  });
}

export function refreshContextSnapshot<TPayload = unknown>(
  input: RuntimeContextRefreshInput<TPayload>,
): RuntimeContextRefreshResult<TPayload> {
  const boundary = assertRefreshBoundary(input.boundary);
  const assembly = assembleContextSnapshot(input.assembly);
  const includedContributionIds = createContributionIdSet(
    assembly.snapshot.contributions,
  );
  const includedConflictCandidates = filterIncludedConflictCandidates(
    input.conflictCandidates,
    includedContributionIds,
  );
  const conflictResolution = resolveContextContributionConflicts({
    candidates: includedConflictCandidates,
  });

  return Object.freeze({
    boundary,
    previousSnapshotId: input.previousSnapshot.snapshotId,
    refreshedSnapshot: createEffectiveSnapshot(
      assembly.snapshot,
      conflictResolution.selected,
      conflictResolution.unresolved,
    ),
    included: assembly.included,
    excluded: assembly.excluded,
    selected: conflictResolution.selected,
    shadowed: conflictResolution.shadowed,
    unresolved: conflictResolution.unresolved,
  });
}

